#![recursion_limit = "256"]
//! Replay byte-compat pin for the stage-loop inversion (design D5, PR-I2).
//!
//! `fixtures/workflow_replay/pre_inversion_run.json` is a run record
//! generated by the released pre-inversion binary (harn 0.9.11, before the
//! per-stage attempt loop moved into `std/workflow/stage.harn`): a
//! deterministic command-verify stage failing 3 attempts under the default
//! retry policy. Two pins:
//!
//! 1. **Replay**: the post-inversion runtime deterministically replays the
//!    pre-inversion record and passes its stage/attempt records through
//!    byte-identical — the persisted `RunStageRecord` format did not change.
//! 2. **Live**: a fresh post-inversion run of the same graph produces
//!    attempt records byte-identical to the pre-inversion fixture after
//!    normalizing only the volatile uuid-v7 `started_at` / `finished_at`
//!    timestamps — the default policy stays a blind retry.

use harn_vm::value::VmError;

const PRE_INVERSION_RUN: &str = include_str!("fixtures/workflow_replay/pre_inversion_run.json");

/// The same graph the fixture was generated with (default retry policy,
/// deterministic failing command verify).
const GRAPH: &str = r#"workflow_graph(
    {
      name: "byte_compat_probe",
      entry: "verify",
      nodes: {
        verify: {
          kind: "verify",
          retry_policy: {max_attempts: 3},
          verify: {command: "echo nope && exit 7", expect_status: 0},
          output_contract: {output_kinds: ["verification_result"]},
        },
      },
      edges: [],
    },
  )"#;

fn run(source: &str) -> Result<String, String> {
    harn_vm::reset_thread_local_state();
    let chunk = harn_vm::compile_source(source)?;
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .map_err(|e| e.to_string())?;
    rt.block_on(async {
        let local = tokio::task::LocalSet::new();
        local
            .run_until(async {
                let mut vm = harn_vm::Vm::new();
                harn_vm::register_vm_stdlib(&mut vm);
                vm.execute(&chunk)
                    .await
                    .map_err(|e: VmError| format!("{e:?}"))?;
                Ok(vm.output().to_string())
            })
            .await
    })
}

fn temp_path(label: &str) -> std::path::PathBuf {
    std::env::temp_dir().join(format!(
        "harn-byte-compat-{label}-{}.json",
        uuid::Uuid::now_v7()
    ))
}

fn stage_attempts(run_record: &serde_json::Value) -> serde_json::Value {
    run_record["stages"][0]["attempts"].clone()
}

/// Normalize the only volatile attempt-record fields (uuid-v7 timestamps) so
/// the remaining bytes must match exactly.
fn normalize_attempt_timestamps(attempts: &mut serde_json::Value) {
    for attempt in attempts.as_array_mut().expect("attempts is an array") {
        let object = attempt.as_object_mut().expect("attempt is an object");
        assert!(
            object.get("started_at").map(|v| v.is_string()) == Some(true)
                && object.get("finished_at").map(|v| v.is_string()) == Some(true),
            "attempt records must carry string started_at/finished_at"
        );
        object.insert("started_at".to_string(), serde_json::json!("<ts>"));
        object.insert("finished_at".to_string(), serde_json::json!("<ts>"));
    }
}

#[test]
fn pre_inversion_record_replays_byte_identical() {
    let fixture: serde_json::Value =
        serde_json::from_str(PRE_INVERSION_RUN).expect("fixture parses");
    let fixture_path = temp_path("fixture");
    std::fs::write(&fixture_path, PRE_INVERSION_RUN).expect("write fixture copy");
    let out_path = temp_path("replayed");

    let source = format!(
        r#"pipeline default() {{
  let graph = {GRAPH}
  let replayed = workflow_execute(
    "byte compat probe",
    graph,
    [],
    {{
      max_steps: 1,
      replay_path: "{fixture}",
      replay_mode: "deterministic",
      persist_path: "{out}",
    }},
  )
  __io_println(replayed.run.metadata.replay_mode)
}}"#,
        fixture = fixture_path.display(),
        out = out_path.display(),
    );
    let output = run(&source).expect("replay executes");
    assert!(output.contains("deterministic"), "output: {output}");

    let replayed: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&out_path).expect("read replayed run"))
            .expect("replayed run parses");

    // Replay passes the pre-inversion attempt records through byte-identical
    // (no timestamp normalization: replay copies the records).
    assert_eq!(
        serde_json::to_string(&stage_attempts(&replayed)).unwrap(),
        serde_json::to_string(&stage_attempts(&fixture)).unwrap(),
        "replayed attempt records must be byte-identical to the pre-inversion fixture"
    );
    for key in [
        "status",
        "outcome",
        "branch",
        "verification",
        "visible_text",
    ] {
        assert_eq!(
            replayed["stages"][0][key], fixture["stages"][0][key],
            "replayed stage field `{key}` must match the pre-inversion fixture"
        );
    }

    let _ = std::fs::remove_file(&fixture_path);
    let _ = std::fs::remove_file(&out_path);
}

#[test]
fn live_default_policy_attempts_match_pre_inversion_bytes() {
    let fixture: serde_json::Value =
        serde_json::from_str(PRE_INVERSION_RUN).expect("fixture parses");
    let out_path = temp_path("live");

    let source = format!(
        r#"pipeline default() {{
  let graph = {GRAPH}
  let live = workflow_execute("byte compat probe", graph, [], {{max_steps: 1, persist_path: "{out}"}})
  __io_println(live.run.stages[0].status)
}}"#,
        out = out_path.display(),
    );
    let output = run(&source).expect("live run executes");
    assert!(output.contains("failed"), "output: {output}");

    let live: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&out_path).expect("read live run"))
            .expect("live run parses");

    let mut live_attempts = stage_attempts(&live);
    let mut fixture_attempts = stage_attempts(&fixture);
    normalize_attempt_timestamps(&mut live_attempts);
    normalize_attempt_timestamps(&mut fixture_attempts);
    assert_eq!(
        serde_json::to_string(&live_attempts).unwrap(),
        serde_json::to_string(&fixture_attempts).unwrap(),
        "post-inversion default-policy attempt records must be byte-identical to the \
         pre-inversion fixture (modulo uuid-v7 timestamps)"
    );
    for key in ["status", "outcome", "branch", "verification"] {
        assert_eq!(
            live["stages"][0][key], fixture["stages"][0][key],
            "live stage field `{key}` must match the pre-inversion fixture"
        );
    }

    let _ = std::fs::remove_file(&out_path);
}
